<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {api,dateToday} from './api';
const props=defineProps<{children:{id:string;name:string}[]}>();
const tab=ref('published'),tasks=ref<any[]>([]),publications=ref<any[]>([]),nextOffset=ref<number|null>(null);
const taskIds=ref<string[]>([]),childIds=ref<string[]>([]),content=ref(''),priority=ref('normal'),editing=ref<any>(null),removing=ref<any>(null),busy=ref(false),error=ref(''),notice=ref('');
const sheet=ref<'edit'|'assign'|'remove'|null>(null),sheetEl=ref<HTMLElement>(),mode=ref('range'),keyboardInset=ref(0);
function viewportChanged(){const view=window.visualViewport;keyboardInset.value=view?Math.max(0,window.innerHeight-view.height-view.offsetTop):0;}
const startDate=ref(dateToday()),endDate=ref(dateToday()),weeks=ref(1),weekdays=ref([1,2,3,4,5]);
const week=['一','二','三','四','五','六','日'];let oldOverflow='',noticeTimer:ReturnType<typeof setTimeout>;
watch(sheet,async (value,previous)=>{if(value){if(!previous)oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();sheetEl.value?.focus({preventScroll:true});}else document.body.style.overflow=oldOverflow;});
watch(notice,value=>{clearTimeout(noticeTimer);if(value)noticeTimer=setTimeout(()=>notice.value='',6000);});
const preview=computed(()=>{const first=Date.parse(startDate.value+'T00:00:00Z');const last=mode.value==='weekly'?first+Number(weeks.value)*7*86400000-86400000:Date.parse(endDate.value+'T00:00:00Z');if(!Number.isFinite(first)||!Number.isFinite(last)||last<first||last-first>365*86400000||(mode.value==='weekly'&&(!Number.isInteger(Number(weeks.value))||weeks.value<1||weeks.value>52)))return 0;let count=0;for(let date=first;date<=last;date+=86400000)if(mode.value==='range'||weekdays.value.includes(new Date(date).getUTCDay()||7))count++;return count*taskIds.value.length*childIds.value.length;});
function assignedTime(value:string){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value.endsWith('Z')?value:value.replace(' ','T')+'Z'));}
function ruleText(item:any){if(item.mode==='weekly')return '每周'+item.weekdays.map((d:number)=>week[d-1]).join('、')+' · '+item.weeks+'周';if(item.mode==='range')return '按周期 · 每天执行';return '历史日期分配';}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
async function loadTasks(){tasks.value=await api('/household-tasks');taskIds.value=taskIds.value.filter(id=>tasks.value.some(t=>t.id===id));}
async function loadPublications(offset=0){const result=await api('/household-tasks/publications?offset='+offset);publications.value=offset?[...publications.value,...result.items]:result.items;nextOffset.value=result.nextOffset;}
async function switchTab(value:string){if(busy.value)return;sheet.value=null;tab.value=value;await act(()=>value==='published'?loadPublications():loadTasks());}
function openEditor(task?:any){error.value='';editing.value=task??null;content.value=task?.content??'';priority.value=task?.priority??'normal';sheet.value='edit';}
function openPublish(task?:any){if(task)taskIds.value=[task.id];if(!taskIds.value.length)return;error.value='';sheet.value='assign';}
function closeSheet(){if(!busy.value)sheet.value=null;}
async function save(){await act(async()=>{const body={content:content.value,priority:priority.value,...(editing.value?{revision:editing.value.revision}:{})};await api('/household-tasks'+(editing.value?'/'+editing.value.id:''),{method:editing.value?'PUT':'POST',body:JSON.stringify(body)});sheet.value=null;await loadTasks();notice.value='任务清单已保存';});}
async function remove(){await act(async()=>{const task=removing.value;await api('/household-tasks/'+task.id,{method:'DELETE',body:JSON.stringify({revision:task.revision})});sheet.value=null;await loadTasks();notice.value='已移除，发布记录和完成情况保留';});}
async function assign(){await act(async()=>{const schedule=mode.value==='range'?{mode:'range',startDate:startDate.value,endDate:endDate.value}:{mode:'weekly',startDate:startDate.value,weeks:Number(weeks.value),weekdays:weekdays.value};const result=await api('/household-tasks/assign',{method:'POST',body:JSON.stringify({taskIds:taskIds.value,childIds:childIds.value,...schedule})});sheet.value=null;tab.value='published';await loadPublications();notice.value='已发布 '+result.created+' 项，跳过已有 '+result.skipped+' 项';});}
onMounted(()=>{window.visualViewport?.addEventListener('resize',viewportChanged);window.visualViewport?.addEventListener('scroll',viewportChanged);void act(()=>loadPublications());});onUnmounted(()=>{window.visualViewport?.removeEventListener('resize',viewportChanged);window.visualViewport?.removeEventListener('scroll',viewportChanged);if(sheet.value)document.body.style.overflow=oldOverflow;clearTimeout(noticeTimer);});
</script>

<template>
 <section class="household-workspace">
  <div class="household-tabs" role="tablist" aria-label="家庭任务"><button role="tab" :aria-selected="tab==='published'" :class="{active:tab==='published'}" :disabled="busy" @click="switchTab('published')">任务发布清单</button><button role="tab" :aria-selected="tab==='library'" :class="{active:tab==='library'}" :disabled="busy" @click="switchTab('library')">任务清单</button></div>
  <p v-if="error&&!sheet" class="error" role="alert">{{error}}</p><Transition name="toast"><p v-if="notice" class="household-toast" role="status">{{notice}}</p></Transition>
  <Transition name="tab-fade" mode="out-in"><section v-if="tab==='published'" key="published" role="tabpanel" aria-label="任务发布清单">
   <p v-if="!publications.length" class="empty">{{busy?'正在加载…':'还没有发布的家庭任务'}}<button v-if="!busy" class="quiet" @click="switchTab('library')">去任务清单新增</button></p>
   <article v-for="item in publications" :key="item.id" class="publication-card"><div class="publication-heading"><strong>{{item.childName}}</strong><span class="badge">{{item.total&&item.completed===item.total?'已完成':item.total?'已发布':item.removed?'已移除':'暂无任务'}}</span></div><p class="publication-content">{{item.tasks[0]||'历史家庭任务'}}<span v-if="item.tasks.length>1" class="muted"> 等{{item.tasks.length}}项</span></p><details v-if="item.tasks.length>1"><summary>查看任务</summary><p v-for="(task,index) in item.tasks" :key="index" class="publication-content">{{task}}</p></details><div class="publication-meta"><span>分配于 {{assignedTime(item.assignedAt)}}</span><span>执行 {{item.startDate}}{{item.endDate&&item.endDate!==item.startDate?' 至 '+item.endDate:''}}</span><span>{{ruleText(item)}}</span><span>已完成 {{item.completed}} / {{item.total}}<template v-if="item.removed"> · 已移除{{item.removed}}项</template></span></div></article>
   <button v-if="nextOffset!==null" class="outline wide" :disabled="busy" @click="act(()=>loadPublications(nextOffset!))">加载更多</button>
  </section><section v-else key="library" role="tabpanel" aria-label="任务清单">
   <p v-if="!tasks.length" class="empty">{{busy?'正在加载…':'清单为空，点击底部新增任务'}}</p><article v-for="task in tasks" :key="task.id" class="publication-card"><label class="household-select"><input v-model="taskIds" type="checkbox" :value="task.id" :disabled="busy"><span class="publication-content">{{task.content}}</span></label><div class="card-actions"><span v-if="task.priority==='high'" class="priority-label">优先</span><button class="quiet" :disabled="busy" @click="openPublish(task)">发布</button><button class="quiet" :disabled="busy" @click="openEditor(task)">编辑</button><button class="quiet danger" :disabled="busy" @click="removing=task;error='';sheet='remove'">移除</button></div></article>
   <div v-if="!sheet" class="bottom-dock household-dock"><button class="outline" :disabled="busy" @click="openEditor()">新增任务</button><button class="primary" :disabled="busy||!taskIds.length" @click="openPublish()">发布所选（{{taskIds.length}}）</button></div>
  </section></Transition>
  <Transition name="mobile-sheet"><div v-if="sheet" class="modal-backdrop" :style="{bottom:keyboardInset+'px'}" @click.self="closeSheet" @keydown.esc="closeSheet"><section ref="sheetEl" class="modal household-sheet" :style="{maxHeight:keyboardInset?'calc(92dvh - '+keyboardInset+'px)':undefined}" role="dialog" aria-modal="true" :aria-label="sheet==='edit'?'编辑清单任务':sheet==='assign'?'发布家庭任务':'移除清单任务'" tabindex="-1"><header><h2>{{sheet==='edit'?(editing?'编辑任务':'新增任务'):sheet==='assign'?'发布任务':'移除任务'}}</h2><button class="quiet" :disabled="busy" @click="closeSheet">关闭</button></header><p v-if="error" class="error" role="alert">{{error}}</p>
   <form v-if="sheet==='edit'" @submit.prevent="save"><label>任务要求<textarea v-model="content" rows="4" maxlength="3000" required placeholder="例如：弹钢琴20分钟"></textarea></label><label>优先级<select v-model="priority"><option value="normal">普通任务</option><option value="high">优先任务</option></select></label><div class="modal-actions"><button class="primary wide" :disabled="busy||!content.trim()">保存到任务清单</button></div></form>
   <template v-else-if="sheet==='assign'"><p class="muted small">已选{{taskIds.length}}项任务</p><fieldset><legend>分配给</legend><label v-for="child in props.children" :key="child.id" class="check"><input v-model="childIds" type="checkbox" :value="child.id" :disabled="busy">{{child.name}}</label></fieldset><div class="household-tabs" role="group" aria-label="分配方式"><button :aria-pressed="mode==='range'" :class="{active:mode==='range'}" :disabled="busy" @click="mode='range';error=''">按周期</button><button :aria-pressed="mode==='weekly'" :class="{active:mode==='weekly'}" :disabled="busy" @click="mode='weekly';error=''">按每周</button></div><label>开始日期<input v-model="startDate" type="date" :disabled="busy"></label><Transition name="tab-fade" mode="out-in"><div v-if="mode==='range'" key="range"><label>结束日期<input v-model="endDate" type="date" :min="startDate" :disabled="busy"></label><p class="muted small">起止日期内每天执行。</p></div><div v-else key="weekly"><label>执行周数<input v-model.number="weeks" type="number" min="1" max="52" inputmode="numeric" :disabled="busy"></label><fieldset><legend>每周星期</legend><label v-for="(day,index) in week" :key="day" class="check"><input v-model="weekdays" type="checkbox" :value="index+1" :disabled="busy">周{{day}}</label></fieldset></div></Transition><p class="muted small">预计 {{preview}} 项；已有任务自动跳过。</p><div class="modal-actions"><button class="primary wide" :disabled="busy||!preview||preview>2000" @click="assign">{{busy?'发布中…':'确认发布（'+preview+'项）'}}</button></div></template>
   <template v-else><p>从任务清单移除？已发布任务和完成记录保留。</p><div class="modal-actions"><button class="quiet" :disabled="busy" @click="closeSheet">取消</button><button class="primary" :disabled="busy" @click="remove">确认移除</button></div></template>
  </section></div></Transition>
 </section>
</template>

<style scoped>
.household-workspace{padding-bottom:calc(110px + env(safe-area-inset-bottom))}.household-tabs{display:flex;gap:4px;background:#e9efeb;padding:4px;border-radius:12px;margin:4px 0 18px}.household-tabs button{flex:1;background:transparent;min-height:44px;padding:9px 10px;font-size:15px}.household-tabs button.active{background:white;box-shadow:0 2px 8px #233b3610}.publication-card{background:white;border:1px solid #e1e8e2;border-radius:16px;padding:16px;margin:12px 0}.publication-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.publication-heading strong{font-size:19px;overflow-wrap:anywhere}.publication-content{white-space:pre-wrap;overflow-wrap:anywhere;font-size:17px;margin:12px 0}.publication-meta{display:grid;gap:3px;color:#637a74;font-size:13px}.publication-card summary{font-size:14px;color:#536e65;cursor:pointer}.household-select{display:flex;align-items:flex-start;gap:12px}.household-select input{flex-shrink:0;margin-top:15px}.household-select .publication-content{min-width:0;margin:8px 0}.household-dock{display:flex;gap:10px}.household-dock button{flex:1;min-width:0;padding:10px 8px}.household-sheet{max-width:580px}.household-toast{position:fixed;left:20px;right:20px;top:16px;max-width:540px;margin:0 auto;background:#315f53;color:white;border-radius:12px;padding:14px 18px;z-index:30;box-shadow:0 6px 24px #233b3620}.empty button{display:block;margin:12px auto 0}
</style>
